import unittest,subprocess,sys,pathlib,json,hashlib
from sql_scan import inventory
class ReviewTests(unittest.TestCase):
 def test_function_dml_not_top_level(self):
  s="CREATE FUNCTION f() RETURNS void AS $body$ BEGIN INSERT INTO x VALUES ('a;b'); END $body$ LANGUAGE plpgsql; INSERT INTO x VALUES (1);"
  self.assertEqual([r['kind'] for r in inventory(s)],['CREATE','INSERT'])
 def test_comments_quotes(self):
  s="/* x /* nested; */ z */ CREATE TABLE x (s text DEFAULT ';'); -- hi;\nINSERT INTO x VALUES ('it''s;ok');"
  self.assertEqual([r['kind'] for r in inventory(s)],['CREATE','INSERT'])
 def test_effect_blocks_flagged(self):
  self.assertTrue(all(r['needs_effect_review'] for r in inventory("DO $$ BEGIN PERFORM f(); END $$; WITH x AS (DELETE FROM t RETURNING *) SELECT * FROM x; SELECT cron.schedule('x','* * * * *','select 1');")))
 def test_bad_quote_rejected(self):
  with self.assertRaises(ValueError):inventory("SELECT 'unfinished")
 def test_review_required_before_bootstrap(self):
  r=subprocess.run([sys.executable,str(pathlib.Path(__file__).with_name('runner.py'))],capture_output=True,text=True)
  self.assertNotEqual(r.returncode,0);self.assertIn('missing Claude review approval',r.stderr)
 def test_overlay_hashes(self):
  base=pathlib.Path(__file__).parent;p=json.loads((base/'plan.json').read_text())
  self.assertFalse(p['execution_allowed']);self.assertTrue(p['blockers'])
  for e in p['entries']:
   if 'overlay_candidate' in e:
    self.assertEqual(hashlib.sha256((base/e['overlay_candidate']).read_bytes()).hexdigest(),e['overlay_sha256'])
    self.assertFalse(any(x['kind'] in ('INSERT','UPDATE','DELETE','MERGE') for x in inventory((base/e['overlay_candidate']).read_text())))
if __name__=='__main__':unittest.main()
